using System;
using System.Collections.Generic;
using System.Reflection;
using System.Threading.Tasks;
using ConvexHullDemo;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
public static class VerifyChanTeaching {
 static int checks;
 static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 public static object Algorithm(){checks=0;var sizes=new[]{1,2,20,1000};int defaultEvents=0,circleEvents=0;var r=new System.Random(28);
  foreach(int n in sizes)foreach(bool circle in new[]{false,true})foreach(var mode in new[]{TeachingGranularity.KeySteps,TeachingGranularity.DetailedSteps}){
   var input=new List<TeachingPoint>();var coords=new List<Vector2>();for(int i=0;i<n;i++){var v=circle?new Vector2(Mathf.Cos(i*Mathf.PI*2/n),Mathf.Sin(i*Mathf.PI*2/n))*5:new Vector2((float)r.NextDouble()*20,(float)r.NextDouble()*12);coords.Add(v);input.Add(new TeachingPoint(100+i*3,v));}
   using(var s=TeachingAlgorithmRegistry.Create(TeachingAlgorithmKind.Chan,input,mode)){TeachingEvent e;int candidates=0,confirmed=0;while(s.Advance(4096,out e)!=TeachingAdvance.Complete){Check(s.LastAdvanceComparisons<=4096,"Budget");if(e==null)continue;
    if(e.Operation==TeachingOperation.ChanPartition)for(int i=0;i<s.Unique.Count;i++)Check(s.PointGroups[i]==i/s.ChanGroupSize,"All points colored before hull construction");
    if(e.Operation==TeachingOperation.ChanCandidates){candidates++;Check(Array.IndexOf(e.Path,e.Point)>=0,"Winner is group candidate");for(int i=0;i<e.Path.Length;i++)if(e.Path[i]>=0)Check(s.PointGroups[e.Path[i]]==i,"Candidate belongs to group");}
    if(e.Operation==TeachingOperation.Push&&e.Phase=="确认全局边界")confirmed++;
   }var expected=ConvexHull2D.Compute(coords);Check(expected.Count==s.Result.Count,"Hull size");for(int i=0;i<expected.Count;i++)Check(expected[i]==s.Unique[s.Result[i]],"Exact hull");Check(candidates==confirmed,"Query before every confirmation");if(mode==TeachingGranularity.KeySteps&&n==1000&&circle)circleEvents=s.VisibleEvents;
  }}
  var demo=UnityEngine.Object.FindFirstObjectByType<ConvexHullDemoController>();var data=new List<TeachingPoint>();for(int i=0;i<demo.initialPoints.Length;i++)data.Add(new TeachingPoint(i+1,demo.initialPoints[i]));
  using(var s=TeachingAlgorithmRegistry.Create(TeachingAlgorithmKind.Chan,data,TeachingGranularity.KeySteps)){TeachingEvent e;while(s.Advance(4096,out e)!=TeachingAdvance.Complete){}defaultEvents=s.VisibleEvents;Check(s.RetryCount==1&&defaultEvents<500,"Default retry preserved with full animation");}
  return new{passed=true,checks,defaultEvents,uncompressedDefaultSeconds=defaultEvents*.6f,circleEvents};
 }
 public static object Visual(){checks=0;var d=UnityEngine.Object.FindFirstObjectByType<ConvexHullDemoController>();var p=d.playback;p.Stop();d.HideHelp();p.SelectAlgorithm(TeachingAlgorithmKind.Chan);int revision=d.HullRevision;Check(p.Play(out var error),error);p.Pause();int groupFrames=0,rays=0;try{for(int guard=0;p.IsActive&&guard<10000;guard++){var e=p.CurrentEvent;var s=p.CurrentTrace;
  if(e.Operation==TeachingOperation.ChanPartition){groupFrames++;Check(p.overlay.ActiveGroupCount==0,"Partition does not reveal unbuilt hulls");var block=new MaterialPropertyBlock();foreach(var point in d.Points){int idx=-1;for(int i=0;i<s.Unique.Count;i++)if(s.Unique[i]==point.Position)idx=i;var view=d.pointsRoot.Find("Point "+point.Id).GetComponent<HullPointView>();view.dot.GetPropertyBlock(block);Check(block.GetColor("_Color")==HullTeachingOverlay.ChanGroupColor(s.PointGroups[idx]),"Actual group color");Check(!view.selectionRing.gameObject.activeSelf,"Selection hidden");}
   var panel=UnityEngine.Object.FindFirstObjectByType<HullPlaybackPanel>();var labels=(List<Text>)typeof(HullPlaybackPanel).GetField("labels",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(panel);for(int i=0;i<s.Unique.Count;i++)Check(labels[i].text==s.DisplayNumbers[i]+"·组"+(s.PointGroups[i]+1),"Correct group label");}
  if(e.Operation==TeachingOperation.ChanCandidates){rays++;p.overlay.Draw(1);Check(p.overlay.transition.positionCount==2&&p.overlay.candidateRing.gameObject.activeSelf,"Winner shown");}
  if(e.Operation==TeachingOperation.Finish)break;p.NextStep();p.Tick(1);p.Tick(1);
 }Check(groupFrames==2&&rays==10,"Both default rounds compact");Check(d.HullRevision==revision,"No realtime refresh");}finally{p.Stop();}
 var restored=new MaterialPropertyBlock();foreach(var point in d.Points){var view=d.pointsRoot.Find("Point "+point.Id).GetComponent<HullPointView>();view.dot.GetPropertyBlock(restored);bool boundary=false;foreach(var v in d.Hull)if(v==point.Position)boundary=true;Check(restored.GetColor("_Color")==(boundary?d.hullColor:d.innerColor),"Normal color restored");}Check(p.overlay.ActiveGroupCount==0,"No leftover rays");return new{passed=true,checks};
 }
 public static object LargePlayback(){checks=0;var d=UnityEngine.Object.FindFirstObjectByType<ConvexHullDemoController>();var p=d.playback;p.Stop();d.HideHelp();d.ClearPoints();for(int i=0;i<1000;i++)d.AddPoint(new Vector2(Mathf.Cos(i*Mathf.PI*2/1000),Mathf.Sin(i*Mathf.PI*2/1000))*5);d.FlushChanges();p.SelectAlgorithm(TeachingAlgorithmKind.Chan);Check(p.Play(out var error),error);float seconds=0;for(int i=0;p.IsActive&&i<150000;i++){p.Tick(1f/60);seconds+=1f/60;}Check(!p.IsActive&&seconds<2500,"1000 boundary points full animation completes within bounded timeline");Check(p.overlay.ActiveGroupCount==0,"Large playback cleans overlays");return new{passed=true,checks,simulatedSeconds=seconds};}
 public static object DefaultTiming(){checks=0;var d=UnityEngine.Object.FindFirstObjectByType<ConvexHullDemoController>();var p=d.playback;p.Stop();d.HideHelp();p.SelectAlgorithm(TeachingAlgorithmKind.Chan);Check(p.Play(out var error),error);float seconds=0;for(int i=0;p.IsActive&&i<20000;i++){p.Tick(1f/60);seconds+=1f/60;}Check(!p.IsActive&&seconds<100,"Full default sequence completes without skipped events");return new{passed=true,checks,simulatedSeconds=seconds};}
 public static object Order(){checks=0;var d=UnityEngine.Object.FindFirstObjectByType<ConvexHullDemoController>();var input=new List<TeachingPoint>();for(int i=0;i<d.initialPoints.Length;i++)input.Add(new TeachingPoint(i,d.initialPoints[i]));using(var s=TeachingAlgorithmRegistry.Create(TeachingAlgorithmKind.Chan,input,TeachingGranularity.KeySteps)){int built=0,working=-1,pushes=0,pops=0,queries=0;TeachingEvent e;while(s.Advance(4096,out e)!=TeachingAdvance.Complete){if(e==null)continue;if(e.Operation==TeachingOperation.ChanPartition){built=0;working=-1;}if(e.Operation==TeachingOperation.ChanBuildStart){Check(e.Group==10000+built,"Groups constructed sequentially");working=e.Group;}if(e.Operation==TeachingOperation.Push&&(e.Phase=="下链"||e.Phase=="上链")){Check(working>=10000,"Andrew follows build start");pushes++;}if(e.Operation==TeachingOperation.Pop)pops++;if(e.Operation==TeachingOperation.ChanGroupComplete){Check(e.Group==working,"Working group completed before next");built++;working=-1;}if(e.Operation==TeachingOperation.ChanQueryStart){Check(built==(s.Unique.Count+s.ChanGroupSize-1)/s.ChanGroupSize&&working==-1,"All subhulls completed before global queries");queries++;}}Check(pushes>0&&pops>0&&queries>0,"Andrew and query processes fully visible");return new{passed=true,checks,pushes,pops,queries};}}
 public static async Task<string> PreviewBuild(){var d=UnityEngine.Object.FindFirstObjectByType<ConvexHullDemoController>();var p=d.playback;p.Stop();d.HideHelp();p.SelectAlgorithm(TeachingAlgorithmKind.Chan);if(!p.Play(out var error))throw new Exception(error);p.Pause();int added=0;for(int i=0;i<1000;i++){if(p.CurrentEvent.Operation==TeachingOperation.Push&&p.CurrentEvent.Phase=="下链")added++;if(added==2)break;p.NextStep();p.Tick(1);p.Tick(1);}p.overlay.Draw(1);EditorApplication.isPaused=true;EditorApplication.Step();await Task.Delay(200);Canvas.ForceUpdateCanvases();return "Only first group is being constructed";}
 public static async Task<string> Preview(){var d=UnityEngine.Object.FindFirstObjectByType<ConvexHullDemoController>();d.playback.Stop();d.HideHelp();d.playback.SelectAlgorithm(TeachingAlgorithmKind.Chan);if(!d.playback.Play(out var error))throw new Exception(error);d.playback.Pause();for(int i=0;i<1000;i++){if(d.playback.CurrentEvent.Operation==TeachingOperation.ChanQuery&&!d.playback.CurrentEvent.Improved&&d.playback.CurrentEvent.PreviousBest>=0)break;d.playback.NextStep();d.playback.Tick(1);d.playback.Tick(1);}d.playback.overlay.Draw(1);EditorApplication.isPaused=true;EditorApplication.Step();await Task.Delay(200);Canvas.ForceUpdateCanvases();return "Chan grouped candidates visible";}
}
